files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  background: #1a1a2e;
  color: #e0e0e0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  margin: 0;
}

.card {
  background: #16213e;
  border-radius: 12px;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
  border: 1px solid #0f3460;
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 16px;
  color: #e94560;
  letter-spacing: 1px;
}

.counts {
  display: flex;
  gap: 24px;
  margin-bottom: 20px;
  font-size: 1rem;
  color: #a0a0b0;
}

.counts span span {
  color: #e94560;
  font-weight: 700;
}

.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
}

#todo-input {
  flex: 1;
  padding: 12px;
  font-size: 1rem;
  border: 2px solid #0f3460;
  border-radius: 8px;
  background: #1a1a2e;
  color: #e0e0e0;
  outline: none;
  transition: border-color 0.2s;
}

#todo-input:focus {
  border-color: #e94560;
}

#todo-input::placeholder {
  color: #6a6a7a;
}

#todo-add {
  padding: 12px 20px;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  background: #e94560;
  color: #fff;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

#todo-add:hover {
  background: #c73650;
}

#todo-add:active {
  transform: scale(0.96);
}

#todo-add:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}

.task-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.task-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: #1a1a2e;
  border-radius: 8px;
  border: 1px solid #0f3460;
  transition: border-color 0.2s;
}

.task-item:hover {
  border-color: #e94560;
}

.task-item input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: #e94560;
  cursor: pointer;
  flex-shrink: 0;
}

.task-item span {
  flex: 1;
  font-size: 1rem;
  word-break: break-word;
}

.task-item.completed span {
  text-decoration: line-through;
  color: #6a6a7a;
}

.delete-btn {
  padding: 8px 12px;
  font-size: 1rem;
  border: none;
  border-radius: 6px;
  background: #0f3460;
  color: #e0e0e0;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  flex-shrink: 0;
}

.delete-btn:hover {
  background: #e94560;
  color: #fff;
}

.delete-btn:active {
  transform: scale(0.92);
}

.delete-btn:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  .input-row {
    flex-direction: column;
  }
  .counts {
    flex-direction: column;
    gap: 8px;
  }
}

let tasks = [];
let nextId = 1;

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');

function updateCounts() {
  totalEl.textContent = tasks.length;
  remainingEl.textContent = tasks.filter(t => !t.completed).length;
}

function createTaskElement(task) {
  const li = document.createElement('li');
  li.className = 'task-item';
  li.dataset.id = task.id;

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.id = `todo-check-${task.id}`;
  checkbox.checked = task.completed;
  checkbox.addEventListener('change', () => {
    task.completed = checkbox.checked;
    li.classList.toggle('completed', task.completed);
    updateCounts();
  });

  const label = document.createElement('label');
  label.htmlFor = checkbox.id;
  label.className = 'visually-hidden';
  label.textContent = `Mark task ${task.id} as complete`;

  const span = document.createElement('span');
  span.id = `todo-text-${task.id}`;
  span.textContent = task.text;

  const delBtn = document.createElement('button');
  delBtn.id = `todo-delete-${task.id}`;
  delBtn.className = 'delete-btn';
  delBtn.textContent = '✕';
  delBtn.setAttribute('aria-label', `Delete task ${task.id}`);
  delBtn.addEventListener('click', () => {
    tasks = tasks.filter(t => t.id !== task.id);
    li.remove();
    updateCounts();
  });

  li.append(checkbox, label, span, delBtn);
  return li;
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;

  const task = { id: nextId++, text, completed: false };
  tasks.push(task);
  list.appendChild(createTaskElement(task));
  input.value = '';
  input.focus();
  updateCounts();
}

addBtn.addEventListener('click', addTask);
input.addEventListener('keydown', e => {
  if (e.key === 'Enter') addTask();
});

updateCounts();
